<script setup>
import AccessibleButton from '../../components/AccessibleButton.vue'
import {ref} from 'vue'
import GroupCompanions from '../../components/GroupCompanions.vue'
import GroupWorks from '../../components/GroupWorks.vue'
import {onLoad} from '@dcloudio/uni-app'
import {request} from '../../utils/request'
const id=ref(''),group=ref(null),messages=ref([]),loading=ref(false),busy=ref(false),error=ref(''),content=ref(''),hasMore=ref(false)
const path=()=>'/api/groups/'+id.value
async function load(){loading.value=true;error.value='';try{const [g,m]=await Promise.all([request({url:path()}),request({url:path()+'/messages'})]);group.value=g;messages.value=m;hasMore.value=m.length===50}catch(e){group.value=null;messages.value=[];error.value=e.message||'加载失败'}finally{loading.value=false}}
async function earlier(){if(busy.value||!messages.value.length)return;busy.value=true;try{const rows=await request({url:path()+'/messages',data:{before:messages.value[messages.value.length-1].id}});messages.value.push(...rows);hasMore.value=rows.length===50}catch(e){error.value=e.message}finally{busy.value=false}}
async function send(){if(busy.value||!content.value.trim())return;busy.value=true;error.value='';try{await request({url:path()+'/messages',method:'POST',data:{content:content.value.trim()}});content.value='';await load()}catch(e){error.value=e.message||'发送失败'}finally{busy.value=false}}
function confirm(title,message,action){uni.showModal({title,content:message,success:async r=>{if(!r.confirm||busy.value)return;busy.value=true;error.value='';try{await action()}catch(e){error.value=e.message||'操作失败'}finally{busy.value=false}}})}
function leave(){confirm('退出小组','退出后将无法查看组内交流。组长需要先转让；最后一名成员退出后小组关闭。',async()=>{await request({url:path()+'/leave',method:'POST'});uni.switchTab({url:'/pages/group/list'})})}
function transfer(member){confirm('转让组长','确认将小组管理权交给 '+member.nickname+'？',async()=>{await request({url:path()+'/leader',method:'PUT',data:{memberId:member.id}});await load()})}
function remove(message){confirm('删除消息','删除后其他成员将无法查看这条消息。',async()=>{await request({url:path()+'/messages/'+message.id,method:'DELETE'});await load()})}
onLoad(options=>{id.value=options.id||'';if(/^\d+$/.test(id.value))load();else error.value='小组编号无效'})
</script>
<template><view class="growth-page"><view class="growth-hero"><text class="growth-eyebrow">同行 · 互助</text><text class="growth-title">{{group?.name||'小组空间'}}</text><text class="growth-subtitle">尊重彼此的节奏，不分享他人的隐私。</text></view><view v-if="error" class="growth-error">{{error}}<AccessibleButton class="growth-button secondary" :disabled="loading" @click="load">重新读取</AccessibleButton></view><text v-if="loading" class="growth-muted">正在读取小组…</text><template v-if="group"><view class="growth-card"><text class="growth-card-title">关于小组</text><text class="group-description">{{group.description||'一起创作，一起交流。'}}</text><text class="growth-muted">{{group.member_count}} / {{group.max_count}} 人 · {{group.myRole}} · {{Number(group.status)===1?'开放中':'已关闭'}}</text><view v-for="member in group.members" :key="member.id" class="member-row"><text>{{member.nickname}} · {{member.role}}</text><AccessibleButton v-if="group.myRole==='组长'&&member.role!=='组长'&&Number(group.status)===1" size="mini" :disabled="busy" @click="transfer(member)">转让组长</AccessibleButton></view><AccessibleButton class="growth-button secondary" :disabled="busy" @click="leave">退出小组</AccessibleButton></view>
<GroupCompanions v-if="Number(group.status)===1" :group-id="id" :members="group.members" :my-member-id="group.myMemberId"/><GroupWorks v-if="Number(group.status)===1" :group-id="id"/><view class="growth-card"><text class="growth-card-title">组内交流</text><text class="growth-muted">仅小组成员可见。消息加密保存；作者或组长可以删除消息。</text><template v-if="Number(group.status)===1"><textarea v-model="content" aria-label="组内交流内容" class="growth-input growth-textarea" maxlength="1000" placeholder="分享手作体验，或给同行者一句支持…"/><AccessibleButton class="growth-button" :disabled="busy||!content.trim()" @click="send">{{busy?'处理中…':'发送到小组'}}</AccessibleButton></template><view class="growth-row"><AccessibleButton class="growth-button secondary" :disabled="loading||busy" @click="load">刷新交流</AccessibleButton></view><view v-for="message in messages" :key="message.id" class="message"><view class="growth-row growth-spread"><text>{{message.mine?'我':message.nickname}}</text><AccessibleButton v-if="message.mine||group.myRole==='组长'" size="mini" :disabled="busy" @click="remove(message)">删除</AccessibleButton></view><text class="group-description">{{message.content}}</text><text class="growth-muted">{{String(message.create_time||'').replace('T',' ').slice(0,16)}}</text></view><text v-if="!messages.length" class="growth-muted">还没有交流，从一句简单的问候开始。</text><AccessibleButton v-if="hasMore" class="growth-button secondary" :disabled="busy" @click="earlier">查看更早消息</AccessibleButton></view></template><text class="growth-foot">本系统不能替代专业心理咨询</text></view></template>
<style src="../../styles/growth.css"></style><style scoped>.group-description{display:block;white-space:pre-wrap;font-size:28rpx;line-height:1.9;margin:20rpx 0}.member-row{display:flex;align-items:center;justify-content:space-between;gap:20rpx;padding:18rpx 0;border-bottom:1rpx solid #e5ece7;font-size:26rpx}.member-row button,.message button{margin:0;font-size:23rpx}.message{padding:28rpx 0;border-bottom:1rpx solid #e5ece7}</style>
